module level_sync #(parameter int STAGES=2) (input logic clk_d, rst_ni, input logic async_in, output logic sync_out);
  (* ASYNC_REG = "TRUE" *) logic [STAGES-1:0] pipe;
  always_ff @(posedge clk_d or negedge rst_ni)
    if (!rst_ni) pipe <= '0;
    else pipe <= {pipe[STAGES-2:0], async_in};
  assign sync_out = pipe[STAGES-1];
endmodule

test.testbench:
module tb_level_sync;
  logic clk=0, rst_n=0, async_in=0, sync_out;
  int cycles=0;
  always #5 clk=~clk;
  level_sync dut(.clk_d(clk),.rst_ni(rst_n),.async_in(async_in),.sync_out(sync_out));
  initial begin
    repeat(2) @(posedge clk); #1; rst_n=1;
    @(negedge clk); async_in=1;
    repeat(2) begin @(posedge clk); #1; cycles++; end
    if (sync_out!==1) $fatal(1,"level was not observed after synchronizer latency");
    @(negedge clk); async_in=0;
    repeat(2) @(posedge clk); #1;
    if (sync_out!==0) $fatal(1,"deasserted level did not propagate");
    $display("PASS: stable-level synchronization latency"); $finish;
  end
  // Assumption: async_in remains stable across at least two destination edges.
endmodule

