module elastic1 #(parameter int W=16) (input logic clk,rst_n, input logic in_valid, output logic in_ready, input logic [W-1:0] in_data, output logic out_valid, input logic out_ready, output logic [W-1:0] out_data);
  logic full; logic [W-1:0] data_q;
  assign in_ready = !full || out_ready;
  assign out_valid = full; assign out_data = data_q;
  always_ff @(posedge clk or negedge rst_n)
    if (!rst_n) begin full<=0; data_q<='0; end
    else if (in_ready) begin full<=in_valid; if (in_valid) data_q<=in_data; end
endmodule

test.testbench:
module tb_elastic1;
 logic clk=0,rst_n=0,iv=0,ir,ov,orr=0; logic [7:0] id=0,od;
 byte expected[$]; byte got;
 always #5 clk=~clk;
 elastic1 #(.W(8)) dut(clk,rst_n,iv,ir,id,ov,orr,od);
 initial begin
   repeat(2) @(posedge clk);
   @(negedge clk); rst_n=1;
   for (int n=0;n<12;n++) begin
     @(negedge clk); iv=1; id=n; orr=(n%3!=0);
     @(posedge clk);
     // Sample pre-NBA interface values at the active edge. Retire old data
     // before enqueueing a replacement accepted on this same edge.
     if (ov && orr) begin
       if (expected.size()==0) $fatal(1,"unexpected output transfer");
       got=expected.pop_front();
       if (od!==got) $fatal(1,"ordering/data mismatch: got %0d expected %0d",od,got);
     end
     if (iv && ir) expected.push_back(id);
     #1;
     if (ov && !orr && expected.size()==0) $fatal(1,"stalled item was lost");
   end
   @(negedge clk); iv=0; orr=1;
   repeat(3) begin
     @(posedge clk);
     if (ov && orr) begin
       if (expected.size()==0) $fatal(1,"unexpected drain transfer");
       got=expected.pop_front();
       if (od!==got) $fatal(1,"drain ordering/data mismatch");
     end
     #1;
   end
   if (expected.size()!=0 || ov) $fatal(1,"undrained output queue");
   $display("PASS: handshake-driven elastic buffer scoreboard"); $finish;
 end
endmodule

