module rv_reg #(parameter int W=32)(input logic clk,rst_n, input logic s_valid,output logic s_ready,input logic [W-1:0] s_data,output logic m_valid,input logic m_ready,output logic [W-1:0] m_data);
 logic full; logic [W-1:0] q;
 assign s_ready=!full || m_ready; assign m_valid=full; assign m_data=q;
 always_ff @(posedge clk or negedge rst_n)
  if(!rst_n) begin full<=0; q<='0; end
  else if(s_ready) begin full<=s_valid; if(s_valid) q<=s_data; end
endmodule

