module tb_rv_reg;
 logic clk=0,rst_n=0,sv=0,sr,mv,mr=0; logic [7:0] sd=0,md;
 always #5 clk=~clk;
 rv_reg #(.W(8)) dut(clk,rst_n,sv,sr,sd,mv,mr,md);
 initial begin
  repeat(2) @(posedge clk);
  @(negedge clk); rst_n=1;
  @(negedge clk); sv=1; sd=8'hA1; mr=0; #1;
  if(!sr) $fatal(1,"empty register must accept first beat");
  @(posedge clk); #1;
  if(!mv || md!==8'hA1) $fatal(1,"first beat not stored");
  repeat(2) begin
   @(negedge clk);
   if(!mv || md!==8'hA1) $fatal(1,"stalled beat changed before edge");
   @(posedge clk); #1;
   if(!mv || md!==8'hA1) $fatal(1,"stalled beat was lost or changed");
  end
  @(negedge clk); sd=8'hB2; mr=1; #1;
  if(!(sv && sr && mv && mr)) $fatal(1,"expected simultaneous retire/replace handshake");
  @(posedge clk); #1;
  if(!mv || md!==8'hB2) $fatal(1,"replacement beat not captured after handshake");
  @(negedge clk); sv=0; mr=0;
  if(!mv || md!==8'hB2) $fatal(1,"replacement beat not retained under stall");
  @(posedge clk); #1;
  if(!mv || md!==8'hB2) $fatal(1,"replacement beat changed during stall");
  @(negedge clk); mr=1; #1;
  if(!(mv && mr)) $fatal(1,"expected final drain handshake");
  @(posedge clk); #1;
  if(mv) $fatal(1,"output did not drain");
  $display("PASS: stall stability and full-rate replacement"); $finish;
 end
endmodule

