module sva_contract #(parameter int W=8)(input logic clk,rst_n,valid,ready,input logic [W-1:0] data);
  property p_hold_while_stalled;
    @(posedge clk) disable iff (!rst_n) valid && !ready |=> valid && $stable(data);
  endproperty
  a_hold_while_stalled: assert property(p_hold_while_stalled);
  c_stall_seen: cover property(@(posedge clk) disable iff(!rst_n) valid && !ready ##1 valid && ready);
endmodule

