interface rv_if(input logic clk);
  logic valid,ready; logic [7:0] data;
endinterface
import uvm_pkg::*;

class rv_item extends uvm_sequence_item;
  rand bit [7:0] data; rand int unsigned gap;
  constraint c_gap { gap inside {[0:3]}; }
  `uvm_object_utils_begin(rv_item)
    `uvm_field_int(data,UVM_ALL_ON) `uvm_field_int(gap,UVM_ALL_ON)
  `uvm_object_utils_end
  function new(string name="rv_item"); super.new(name); endfunction
endclass

class rv_monitor extends uvm_component;
  `uvm_component_utils(rv_monitor)
  uvm_analysis_port #(rv_item) ap;
  virtual rv_if vif;
  function new(string name,uvm_component parent); super.new(name,parent); ap=new("ap",this); endfunction
  task run_phase(uvm_phase phase);
    rv_item tr;
    forever begin @(posedge vif.clk); if(vif.valid && vif.ready) begin
      tr=rv_item::type_id::create("tr"); tr.data=vif.data; ap.write(tr);
    end end
  endtask
endclass

