module direct_tag #(parameter int AW=16, LINE_BYTES=16, SETS=4, TAGW=AW-$clog2(LINE_BYTES)-$clog2(SETS))
(input logic clk,rst_n,input logic req,input logic [AW-1:0] addr,output logic hit);
 logic [TAGW-1:0] tags[SETS]; logic valid[SETS];
 wire [$clog2(SETS)-1:0] index=addr[$clog2(LINE_BYTES)+$clog2(SETS)-1:$clog2(LINE_BYTES)];
 wire [TAGW-1:0] tag=addr[AW-1:$clog2(LINE_BYTES)+$clog2(SETS)];
 always_comb hit=req && valid[index] && tags[index]==tag;
 always_ff @(posedge clk or negedge rst_n) if(!rst_n) begin for(int i=0;i<SETS;i++) valid[i]<=0; end
 else if(req&&!hit) begin tags[index]<=tag; valid[index]<=1; end
endmodule

