 always #5 clk=~clk;
 direct_tag #(.AW(16),.LINE_BYTES(16),.SETS(4)) dut(clk,rst_n,req,addr,hit);
 task automatic access(input logic [15:0] a,input bit expected_hit);
  @(negedge clk); addr=a; req=1; #1;
  if(hit!==expected_hit) $fatal(1,"addr %h hit=%b expected=%b",a,hit,expected_hit);
  @(posedge clk); #1;
 endtask
 initial begin
  repeat(2) @(posedge clk); #1 rst_n=1;
  access(16'h0120,0); access(16'h0124,1); // same line, different byte offset
  access(16'h0160,0); // same set, different tag, direct-mapped conflict
  access(16'h0120,0); access(16'h0120,1);
  $display("PASS: tag/index/offset exercise"); $finish;
 end
endmodule

