module reset_release #(parameter int N=2)(input logic clk,arst_n,output logic srst_n);
 (* ASYNC_REG="TRUE" *) logic [N-1:0] q;
 always_ff @(posedge clk or negedge arst_n)
   if(!arst_n) q<='0; else q<={q[N-2:0],1'b1};
 assign srst_n=q[N-1];
endmodule
module isolated_bus #(parameter int W=8)(input logic iso_en,input logic [W-1:0] src,output logic [W-1:0] dst);
 assign dst=iso_en?'0:src;
endmodule

