module tb_reset_isolation;
 logic clk=0,arst_n=0,iso=1; logic [7:0] src=8'hA5,dst; logic srst_n;
 always #5 clk=~clk;
 reset_release #(.N(2)) r(clk,arst_n,srst_n);
 isolated_bus #(.W(8)) i(iso,src,dst);
 initial begin
  #1; if(dst!==0) $fatal(1,"isolation clamp failed");
  repeat(2) @(posedge clk); #1; if(srst_n!==0) $fatal(1,"reset released while async reset active");
  @(negedge clk); arst_n=1;
  repeat(2) @(posedge clk); #1; if(srst_n!==1) $fatal(1,"reset did not release after two stages");
  if(dst!==0) $fatal(1,"isolation released unexpectedly");
  @(negedge clk); iso=0; #1; if(dst!==src) $fatal(1,"isolation release failed");
  $display("PASS: reset-release and isolation ordering"); $finish;
 end
endmodule

