module constrained_path #(parameter int W=16)(input logic clk,rst_n,input logic en,input logic [W-1:0] a,b,output logic [W-1:0] q);
 logic [W-1:0] sum;
 always_comb sum=a+b;
 always_ff @(posedge clk or negedge rst_n) if(!rst_n) q<='0; else if(en) q<=sum;
endmodule
