module tb_param_fifo;
 logic clk=0,rst_n=0,push=0,pop=0,full,empty; logic [7:0] din,dout; byte q[$]; byte v;
 always #5 clk=~clk;
 param_fifo #(.W(8),.DEPTH(3)) dut(clk,rst_n,push,pop,din,dout,full,empty);
 initial begin
  repeat(2) @(posedge clk); #1 rst_n=1;
  for(int n=0;n<3;n++) begin @(negedge clk); push=1; din=n+10; if(!full) q.push_back(din); @(posedge clk); #1; end
  if(!full) $fatal(1,"expected full at depth three");
  for(int n=0;n<3;n++) begin @(negedge clk); push=0; pop=1; v=q.pop_front(); if(empty||dout!==v) $fatal(1,"FIFO order/data mismatch"); @(posedge clk); #1; end
  if(!empty) $fatal(1,"expected empty");
  $display("PASS: non-power-of-two parameter configuration"); $finish;
 end
endmodule

module tb_decode2;
 logic [15:0] addr; logic req=1,ha,hb,miss;
 decode2 dut(addr,req,ha,hb,miss);
 task automatic check(input logic [15:0] a,input bit ea,eb,em);
  addr=a; #1;
  if({ha,hb,miss}!=={ea,eb,em}) $fatal(1,"decode mismatch at %h",a);
 endtask
