  check(16'h0000,1,0,0); check(16'h0fff,1,0,0);
  check(16'h1000,0,1,0); check(16'h1fff,0,1,0);
  check(16'h2000,0,0,1);
  req=0; addr=16'h0001; #1; if({ha,hb,miss}!==0) $fatal(1,"inactive request hit");
  $display("PASS: boundaries, unmapped decode, and request gating"); $finish;
